function chronologyTime(record) {
  const sourceTime = Date.parse(record.source_timestamp);
  if (!Number.isNaN(sourceTime)) return sourceTime;
  return Date.parse(record.observed_at);
}

export function orderChronology(records) {
  return records.sort((a, b) => chronologyTime(b) - chronologyTime(a));
}

